func TestOneOfRequestAttributeDefaultVersion(t *testing.T) {
	const noVersion = `{"uuid":"u","name":"n","contentType":"string"}`
	var w RequestAttribute
	assertDefaultRoutes(t, "RequestAttribute", &w, noVersion, "RequestAttributeV2")
}

// 7. ResponseAttribute — discriminator STRING "version" (v2/v3), NO default.
func TestOneOfResponseAttribute(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "v2",
			payload:    `{"version":"v2","uuid":"u","name":"n","label":"L","type":"data","contentType":"string"}`,
			newWrapper: func() oneOfWrapper { return &ResponseAttribute{} },
			wantType:   &ResponseAttributeV2{},
			discSubstr: []string{`"version":"v2"`},
		},
		{
			name:       "v3",
			payload:    `{"version":"v3","uuid":"u","name":"n","label":"L","type":"data","contentType":"string"}`,
			newWrapper: func() oneOfWrapper { return &ResponseAttribute{} },
			wantType:   &ResponseAttributeV3{},
			discSubstr: []string{`"version":"v3"`},
		},
	}
	runDiscriminatorCases(t, "ResponseAttribute", cases)

	assertUnknownDiscriminator(t, "ResponseAttribute",
		&ResponseAttribute{}, `{"version":"v9","uuid":"u","name":"n","label":"L","type":"data","contentType":"string"}`)
}

