func TestOneOfBaseAttributeConstraintDefaultType(t *testing.T) {
	var w BaseAttributeConstraint
	assertDefaultRoutes(t, "BaseAttributeConstraint", &w, `{}`, "RegexpAttributeConstraint")
}

